const page = $input.first().json;
const adfRaw = page.body && page.body.atlas_doc_format ? page.body.atlas_doc_format.value : null;
if (!adfRaw) { throw new Error('Confluence page 1540030465 returned no atlas_doc_format body. Offboarding aborted.'); }
const doc = typeof adfRaw === 'string' ? JSON.parse(adfRaw) : adfRaw;

function textOf(n) {
  if (!n) { return ''; }
  if (n.type === 'text') { return n.text || ''; }
  if (n.type === 'status') { return (n.attrs && n.attrs.text) ? n.attrs.text : ''; }
  if (n.type === 'inlineCard') { return (n.attrs && n.attrs.url) ? n.attrs.url : ''; }
  let out = '';
  const kids = n.content || [];
  for (let i = 0; i < kids.length; i++) { out += textOf(kids[i]); }
  return out;
}

function collectTables(n, acc) {
  if (!n || typeof n !== 'object') { return acc; }
  if (n.type === 'table') { acc.push(n); }
  const kids = n.content || [];
  for (let i = 0; i < kids.length; i++) { collectTables(kids[i], acc); }
  return acc;
}

const tables = collectTables(doc, []);
const expected = ['tool name', 'access granted', 'access owner', 'note', 'fs', 'be', 'fe', 'do', 'qa', 'pd'];
let target = null;
let headerFound = [];
for (let t = 0; t < tables.length; t++) {
  const firstRow = (tables[t].content || [])[0];
  if (!firstRow) { continue; }
  const cells = firstRow.content || [];
  const texts = [];
  for (let c = 0; c < cells.length; c++) { texts.push(textOf(cells[c]).trim().toLowerCase()); }
  if (texts.length >= 4 && texts[0] === 'tool name') { target = tables[t]; headerFound = texts; break; }
}
if (!target) { throw new Error('Could not find the tools table on the General tools page (no table whose first column header is "Tool name"). Structure changed - offboarding aborted.'); }
if (headerFound.length !== expected.length) { throw new Error('General tools table has ' + headerFound.length + ' columns, expected ' + expected.length + '. Structure changed - offboarding aborted.'); }
for (let i = 0; i < expected.length; i++) {
  if (headerFound[i] !== expected[i]) { throw new Error('General tools column ' + (i + 1) + ' is "' + headerFound[i] + '", expected "' + expected[i] + '". Structure changed - offboarding aborted.'); }
}

function primaryOwner(raw) {
  let s = (raw || '').replace(/\([^)]*\)/g, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  if (!s) { return ''; }
  const parts = s.split(/[\/+,&]/);
  return parts[0].trim();
}

const allRows = target.content || [];
const rows = [];
const owners = [];
let category = '';
let categoryCount = 0;
for (let r = 1; r < allRows.length; r++) {
  const cells = allRows[r].content || [];
  const texts = [];
  for (let c = 0; c < cells.length; c++) { texts.push(textOf(cells[c]).replace(/\s+/g, ' ').trim()); }
  const tool = (texts[0] || '').trim();
  if (!tool) { continue; }
  let rest = '';
  for (let c = 1; c < texts.length; c++) { rest += (texts[c] || ''); }
  if (rest.trim() === '') { category = tool; categoryCount++; continue; }
  const ownerRaw = (texts[2] || '').trim();
  rows.push({ category: category, tool: tool, note: (texts[3] || '').trim(), owner_confluence: ownerRaw, owner_key: primaryOwner(ownerRaw) });
  const key = primaryOwner(ownerRaw);
  if (key && owners.indexOf(key) === -1) { owners.push(key); }
}

if (rows.length < 60) { throw new Error('Only ' + rows.length + ' tool rows parsed from the General tools page (expected at least 60). Structure changed - offboarding aborted.'); }

return [{ json: { pageVersion: page.version ? page.version.number : null, toolCount: rows.length, categoryCount: categoryCount, owners: owners, rows: rows } }];

const parsed = $('Parse tools table').first().json;
const rows = $input.all();
const map = {};
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json;
  if (r && r.confluence_owner) { map[String(r.confluence_owner).trim().toLowerCase()] = r.default_email ? String(r.default_email).trim() : ''; }
}
const fields = [];
for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  const known = map[o.toLowerCase()] || '';
  fields.push({ fieldLabel: 'Email - ' + o, fieldType: 'email', defaultValue: known, requiredField: false, placeholder: 'leave empty if nobody should be pinged' });
  fields.push({ fieldLabel: 'Ping - ' + o, fieldType: 'checkbox', fieldOptions: { values: [{ option: 'Needed for this offboarding' }] }, defaultValue: 'Needed for this offboarding' });
}
const unknown = [];
for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  if (!map[o.toLowerCase()]) { unknown.push(o); }
}
return [{ json: { formFieldsJson: JSON.stringify(fields), owners: parsed.owners, unknownOwners: unknown } }];

const answers = $input.first().json;
const parsed = $('Parse tools table').first().json;
const intake = $('Offboarding intake').first().json;

const firstName = String(intake['First name'] || '').trim();
const lastName = String(intake['Last name'] || '').trim();
const personName = (firstName + ' ' + lastName).trim();
const personEmail = String(intake['Work email'] || '').trim();
const lastDay = String(intake['Last working day'] || '').trim();
if (!personName || !personEmail) { throw new Error('Missing name or email from the intake form.'); }

function isTicked(v) {
  if (v === true) { return true; }
  if (Array.isArray(v)) { return v.length > 0; }
  if (typeof v === 'string') { return v.trim() !== '' && v.trim().toLowerCase() !== 'false'; }
  return false;
}

const assignee = {};
const excluded = [];
const noEmail = [];
for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  const email = String(answers['Email - ' + o] || '').trim();
  const ping = isTicked(answers['Ping - ' + o]);
  if (!ping) { assignee[o] = ''; excluded.push(o); continue; }
  if (!email) { assignee[o] = ''; noEmail.push(o); continue; }
  assignee[o] = email;
}

const generatedAt = new Date().toISOString();
const sheetRows = [];
sheetRows.push({ c1: 'Name:', c2: personName, c3: '', c4: '', c5: '', c6: '' });
sheetRows.push({ c1: 'Email:', c2: personEmail, c3: '', c4: '', c5: '', c6: '' });
sheetRows.push({ c1: 'Last working day:', c2: lastDay, c3: '', c4: '', c5: '', c6: '' });
sheetRows.push({ c1: 'Generated:', c2: generatedAt, c3: '', c4: '', c5: '', c6: '' });
sheetRows.push({ c1: '', c2: '', c3: '', c4: '', c5: '', c6: '' });
sheetRows.push({ c1: 'Tool', c2: 'Note', c3: 'Access owner (Confluence)', c4: 'Owner for this offboarding', c5: 'Status', c6: 'Status comments' });

let lastCategory = '';
for (let i = 0; i < parsed.rows.length; i++) {
  const r = parsed.rows[i];
  if (r.category && r.category !== lastCategory) {
    sheetRows.push({ c1: r.category, c2: '', c3: '', c4: '', c5: '', c6: '' });
    lastCategory = r.category;
  }
  sheetRows.push({ c1: r.tool, c2: r.note, c3: r.owner_confluence, c4: assignee[r.owner_key] || '', c5: 'To do', c6: '' });
}

const fileName = personName + ' - Offboarding.xlsx';
return [{ json: { personName: personName, personEmail: personEmail, lastDay: lastDay, fileName: fileName, generatedAt: generatedAt, worksheetName: 'Base tool checklist', toolCount: parsed.rows.length, pageVersion: parsed.pageVersion, assignee: assignee, excludedOwners: excluded.join(', '), ownersWithoutEmail: noEmail.join(', '), rows: sheetRows, formRaw: JSON.stringify({ intake: intake, owners: answers }) } }];

const rec = $input.first().json;
const out = [];
for (let i = 0; i < rec.rows.length; i++) { out.push({ json: rec.rows[i] }); }
return out;

const rec = $('Build offboarding record').first().json;
const file = $('Upload checklist to OneDrive').first().json;
const share = $('Create edit share link').first().json;
const parsed = $('Parse tools table').first().json;
const url = (share && share.link && share.link.webUrl) ? share.link.webUrl : (file.webUrl || '');

const byEmail = {};
for (let i = 0; i < parsed.rows.length; i++) {
  const r = parsed.rows[i];
  const email = rec.assignee[r.owner_key] || '';
  if (!email) { continue; }
  if (!byEmail[email]) { byEmail[email] = []; }
  byEmail[email].push(r.tool);
}

const out = [];
const emails = Object.keys(byEmail);
for (let i = 0; i < emails.length; i++) {
  const email = emails[i];
  const tools = byEmail[email];
  let text = '*Offboarding: ' + rec.personName + '* (' + rec.personEmail + ')\n';
  text += 'Last working day: ' + rec.lastDay + '\n';
  text += 'Checklist: ' + url + '\n\n';
  text += 'You are the access owner for ' + tools.length + ' tool(s) on this checklist:\n';
  for (let t = 0; t < tools.length; t++) { text += '- ' + tools[t] + '\n'; }
  text += '\nPlease remove their access where needed and set each row to *Done* or *Not needed* in the Status column (pick from the dropdown). Reminders follow at 6h, 12h, 24h and 48h for anything still *To do*.';
  out.push({ json: { email: email, toolCount: tools.length, text: text } });
}
return out;

